CREATE PROCEDURE [inventory].[InventoryBalance_Search] @Search NVARCHAR(200)=NULL,@WarehouseId UNIQUEIDENTIFIER=NULL,@ProductId UNIQUEIDENTIFIER=NULL,@PageNumber INT=1,@PageSize INT=20
AS
BEGIN SET NOCOUNT ON;SET @PageNumber=CASE WHEN @PageNumber<1 THEN 1 ELSE @PageNumber END;SET @PageSize=CASE WHEN @PageSize<1 THEN 20 WHEN @PageSize>200 THEN 200 ELSE @PageSize END;
 SELECT b.InventoryBalanceId,b.ProductId,p.ProductCode,p.ProductName,b.WarehouseId,w.WarehouseCode,w.WarehouseName,b.ZoneId,z.ZoneCode,b.BinId,bi.BinCode,b.BatchNo,b.SerialNo,b.QuantityOnHand,b.QuantityReserved,b.QuantityAvailable,b.AverageCost,b.LastPurchaseCost,b.LastUpdated
 FROM inventory.InventoryBalances b INNER JOIN master.Products p ON p.ProductId=b.ProductId INNER JOIN inventory.Warehouses w ON w.WarehouseId=b.WarehouseId LEFT JOIN inventory.WarehouseZones z ON z.ZoneId=b.ZoneId LEFT JOIN inventory.WarehouseBins bi ON bi.BinId=b.BinId
 WHERE(@WarehouseId IS NULL OR b.WarehouseId=@WarehouseId)AND(@ProductId IS NULL OR b.ProductId=@ProductId)AND(@Search IS NULL OR p.ProductCode LIKE'%'+@Search+'%' OR p.ProductName LIKE'%'+@Search+'%' OR b.BatchNo LIKE'%'+@Search+'%' OR b.SerialNo LIKE'%'+@Search+'%')ORDER BY p.ProductName,w.WarehouseName OFFSET(@PageNumber-1)*@PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;
 SELECT COUNT_BIG(*)TotalCount FROM inventory.InventoryBalances b INNER JOIN master.Products p ON p.ProductId=b.ProductId WHERE(@WarehouseId IS NULL OR b.WarehouseId=@WarehouseId)AND(@ProductId IS NULL OR b.ProductId=@ProductId)AND(@Search IS NULL OR p.ProductCode LIKE'%'+@Search+'%' OR p.ProductName LIKE'%'+@Search+'%' OR b.BatchNo LIKE'%'+@Search+'%' OR b.SerialNo LIKE'%'+@Search+'%');END;
